/* What one entry costs in the system prompt: name + description + path.
   The prototype divides characters by four; the real one runs a BPE tokenizer. */
window.chars = (s) => s.name.length + s.desc.length + 60;
window.cost = (s) => Math.round(window.chars(s) / 4);
